import { describe, expect, test } from 'vitest';
import { readonly } from '../../actions/index.ts';
import {
  array,
  intersect,
  map,
  nullable,
  object,
  record,
  set,
  string,
} from '../../schemas/index.ts';
import { parse } from '../parse/index.ts';
import { pipe } from '../pipe/index.ts';
import { safeParse } from '../safeParse/index.ts';
import { Recur } from './recur.ts';
import { recursive } from './recursive.ts';

describe('recursive', () => {
  test('should resolve `Recur` in array item position', () => {
    const TreeSchema = recursive(
      object({ value: string(), children: array(Recur) })
    );

    // Self reference must be resolved to the finished schema
    expect(TreeSchema.entries.children.item).toBe(TreeSchema);

    const input = {
      value: 'a',
      children: [
        { value: 'b', children: [] },
        { value: 'c', children: [{ value: 'd', children: [] }] },
      ],
    };
    expect(parse(TreeSchema, input)).toStrictEqual(input);

    const result = safeParse(TreeSchema, {
      value: 'a',
      children: [{ value: 1, children: [] }],
    });
    expect(result.success).toBe(false);
  });

  test('should resolve `Recur` in record value position', () => {
    const JsonSchema = recursive(record(string(), Recur));
    expect(JsonSchema.value).toBe(JsonSchema);

    const input = { a: { b: {}, c: {} } };
    expect(parse(JsonSchema, input)).toStrictEqual(input);
  });

  test('should resolve `Recur` in map value position', () => {
    const MapSchema = recursive(map(string(), nullable(Recur)));
    expect(MapSchema.value.wrapped).toBe(MapSchema);

    const input = new Map<string, unknown>([
      ['a', new Map([['b', null]])],
      ['c', null],
    ]);
    expect(parse(MapSchema, input)).toStrictEqual(input);
  });

  test('should resolve `Recur` in set value position', () => {
    const SetSchema = recursive(set(array(Recur)));
    expect(SetSchema.value.item).toBe(SetSchema);

    const input = new Set<unknown>([[], [[]]]);
    expect(parse(SetSchema, input)).toStrictEqual(input);
  });

  test('should resolve `Recur` when composed through `pipe`', () => {
    const TreeSchema = recursive(
      pipe(
        object({ value: string(), children: array(Recur) }),
        readonly()
      )
    );

    // Both the shortcut property and the pipe item must be resolved
    expect(TreeSchema.entries.children.item).toBe(TreeSchema);
    expect(TreeSchema.pipe[0].entries.children.item).toBe(TreeSchema);

    const input = { value: 'a', children: [{ value: 'b', children: [] }] };
    expect(parse(TreeSchema, input)).toStrictEqual(input);
  });

  test('should resolve `Recur` when composed through `intersect`', () => {
    const TreeSchema = recursive(
      intersect([
        object({ value: string() }),
        object({ children: array(Recur) }),
      ])
    );

    expect(TreeSchema.options[1].entries.children.item).toBe(TreeSchema);

    const input = { value: 'a', children: [{ value: 'b', children: [] }] };
    expect(parse(TreeSchema, input)).toStrictEqual(input);
  });

  test('should not mutate schemas without a `Recur` placeholder', () => {
    const StringSchema = string();
    const ObjectSchema = object({ name: StringSchema });
    const WrappedSchema = recursive(ObjectSchema);
    expect(WrappedSchema.entries.name).toBe(StringSchema);
  });
});
