import { describe, expectTypeOf, test } from 'vitest';
import { minLength, transform } from '../../actions/index.ts';
import {
  array,
  intersect,
  map,
  nullable,
  object,
  record,
  set,
  string,
} from '../../schemas/index.ts';
import type { InferInput, InferOutput } from '../../types/index.ts';
import { pipe } from '../pipe/pipe.ts';
import { Recur } from './recur.ts';
import { recursive, type RecursiveSchema } from './recursive.ts';

describe('recursive', () => {
  test('should resolve `Recur` in array item position to itself', () => {
    interface TreeNode {
      value: string;
      children: TreeNode[];
    }

    const TreeSchema = recursive(
      object({ value: string(), children: array(Recur) })
    );

    expectTypeOf<InferOutput<typeof TreeSchema>>().toEqualTypeOf<TreeNode>();
    expectTypeOf<InferInput<typeof TreeSchema>>().toEqualTypeOf<TreeNode>();
    expectTypeOf(TreeSchema).toEqualTypeOf<
      RecursiveSchema<typeof TreeSchema.wrapped>
    >();
  });

  test('should resolve `Recur` in record value position to itself', () => {
    type JsonRecord = Record<string, JsonRecord>;

    const JsonSchema = recursive(record(string(), Recur));

    expectTypeOf<InferOutput<typeof JsonSchema>>().toEqualTypeOf<JsonRecord>();
  });

  test('should resolve `Recur` in map value position to itself', () => {
    type NestedMap = ReadonlyMap<string, NestedMap | null>;

    const MapSchema = recursive(map(string(), nullable(Recur)));

    expectTypeOf<InferOutput<typeof MapSchema>>().toEqualTypeOf<NestedMap>();
  });

  test('should resolve `Recur` in set value position to itself', () => {
    type NestedSet = ReadonlySet<NestedSet>;

    const SetSchema = recursive(set(Recur));

    expectTypeOf<InferOutput<typeof SetSchema>>().toEqualTypeOf<NestedSet>();
  });

  test('should compose correctly through `pipe`', () => {
    interface TreeNode {
      value: string;
      children: TreeNode[];
    }
    interface TreeNodeInput {
      value: string;
      children: TreeNodeInput[];
    }

    const TreeSchema = recursive(
      pipe(
        object({
          value: pipe(
            string(),
            transform((input) => input.length)
          ),
          children: array(Recur),
        }),
        minLength(0)
      )
    );

    expectTypeOf<InferOutput<typeof TreeSchema>>().toEqualTypeOf<{
      value: number;
      children: unknown extends never
        ? InferOutput<typeof TreeSchema>[]
        : InferOutput<typeof TreeSchema>[];
    }>();
    expectTypeOf<InferInput<typeof TreeSchema>>().toEqualTypeOf<TreeNodeInput>();
  });

  test('should compose correctly through `intersect`', () => {
    interface TreeNode {
      value: string;
      children: TreeNode[];
    }

    const TreeSchema = recursive(
      intersect([
        object({ value: string() }),
        object({ children: array(Recur) }),
      ])
    );

    expectTypeOf<InferOutput<typeof TreeSchema>>().toEqualTypeOf<TreeNode>();
  });
});
