import { recursive } from './recursive.ts';

import { describe, expectTypeOf, test } from 'vitest';
import { readonly, transform } from '../../actions/index.ts';
import {
  array,
  intersect,
  map,
  nullable,
  object,
  record,
  set,
  string,
} from '../../schemas/index.ts';
import type { InferInput, InferOutput } from '../../types/index.ts';
import { pipe } from '../pipe/pipe.ts';
import { Recur } from './recur.ts';
import { recursive, type RecursiveSchema } from './recursive.ts';

test('should compose correctly through `pipe`', () => {
  interface TreeNodeInput {
    value: string;
    children: TreeNodeInput[];
  }
  interface TreeNodeOutput {
    readonly value: number;
    readonly children: TreeNodeOutput[];
  }

  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const TreeSchema = recursive(
    pipe(
      object({
        value: pipe(
          string(),
          transform((input) => input.length)
        ),
        children: array(Recur),
      }),
      readonly()
    )
  );

  expectTypeOf<
    InferInput<typeof TreeSchema>
  >().toEqualTypeOf<TreeNodeInput>();
  expectTypeOf<
    InferOutput<typeof TreeSchema>
  >().toEqualTypeOf<TreeNodeOutput>();
});

import type { BaseTransformation, SuccessDataset } from '../../types/index.ts';

/**
 * Transform action interface.
 */
export interface TransformAction<TInput, TOutput>
  extends BaseTransformation<TInput, TOutput, never> {
  /**
   * The action type.
   */
  readonly type: 'transform';
  /**
   * The action reference.
   */
  readonly reference: typeof transform;
  /**
   * The transformation operation.
   */
  readonly operation: (input: TInput) => TOutput;
}

/**
 * Creates a custom transformation action.
 *
 * @param operation The transformation operation.
 *
 * @returns A transform action.
 */
// @__NO_SIDE_EFFECTS__
export function transform<TInput, TOutput>(
  operation: (input: TInput) => TOutput
): TransformAction<TInput, TOutput> {
  return {
    kind: 'transformation',
    type: 'transform',
    reference: transform,
    async: false,
    operation,
    '~run'(dataset) {
      // @ts-expect-error
      dataset.value = this.operation(dataset.value);
      // @ts-expect-error
      return dataset as SuccessDataset<TOutput>;
    },
  };
}

